def components(g):
    h,w=len(g),len(g[0]); seen=set(); comps=[]
    for y in range(h):
        for x in range(w):
            if g[y][x] and (y,x) not in seen:
                col=g[y][x]; stack=[(y,x)]; seen.add((y,x)); cells=[]
                while stack:
                    cy,cx=stack.pop(); cells.append((cy,cx))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and g[ny][nx]==col:
                            seen.add((ny,nx)); stack.append((ny,nx))
                comps.append(cells)
    return comps

def slide(g, order_key):
    h,w=len(g),len(g[0])
    out=[[0]*w for _ in range(h)]
    comps=components(g)
    comps.sort(key=order_key)
    for cells in comps:
        best=0
        for s in range(w):  # max feasible shift
            ok=True
            for (y,x) in cells:
                nx=x+s
                if nx>=w or (out[y][nx] and out[y][nx]!=0): ok=False; break
            # careful: out[y][nx] for cell's own... cells not yet placed, out only has placed shapes, and nonzero there means collision
            if ok: best=s
            else: break
        for (y,x) in cells:
            out[y][x+best]=g[y][x]
    return out

orders={
 'bottomup': lambda c: max(c[0] for c in [(y,x) for y,x in c]),
